Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

function Get-UtcIso { ([DateTime]::UtcNow.ToString('o')) }

function Nz {
  param([object]$x)
  if ($null -eq $x) { return "" }
  return [string]$x
}

function Tail-Text {
  param([string]$Text, [int]$MaxChars = 2000)
  if (-not $Text) { return $null }
  if ($Text.Length -le $MaxChars) { return $Text }
  return $Text.Substring($Text.Length - $MaxChars)
}

function Resolve-Python {
  $candidates = @(
    @{ exe='py'; args=@('-3.11') },
    @{ exe='py'; args=@() },
    @{ exe='python'; args=@() }
  )
  foreach ($c in $candidates) {
    try {
      $null = Get-Command $c.exe -ErrorAction Stop
      $out = & $c.exe @($c.args + @('-c', 'import sys; print(sys.version)')) 2>$null
      if ($LASTEXITCODE -eq 0 -and $out) { return $c }
    } catch { }
  }
  return $null
}

function Run-PyCapture {
  param(
    [Parameter(Mandatory=$true)][string]$PyExe,
    [Parameter(Mandatory=$true)][string[]]$PyBase,
    [Parameter(Mandatory=$true)][string[]]$Args
  )
  $out = & $PyExe @($PyBase + $Args) 2>&1
  return [ordered]@{ rc = $LASTEXITCODE; out = ($out | Out-String) }
}

function Ensure-PipPkg {
  param(
    [Parameter(Mandatory=$true)][string]$PyExe,
    [Parameter(Mandatory=$true)][string[]]$PyBase,
    [Parameter(Mandatory=$true)][string]$PackageName,
    [Parameter(Mandatory=$true)][string[]]$CheckArgs,
    [Parameter(Mandatory=$true)][string]$ToolKey,
    [Parameter(Mandatory=$true)][hashtable]$Result
  )

  # check
  $chk = Run-PyCapture -PyExe $PyExe -PyBase $PyBase -Args $CheckArgs
  if ($chk.rc -eq 0) {
    $Result.tools[$ToolKey] = ($chk.out.Trim())
    $Result.actions += ($ToolKey + '_detected: python_module')
    return
  }

  # install (global)
  $Result.actions += ('pip_install_upgrade: ' + $PackageName)
  $inst = Run-PyCapture -PyExe $PyExe -PyBase $PyBase -Args @('-m','pip','install','-U',$PackageName,'--disable-pip-version-check','--no-input')
  if ($inst.rc -ne 0) {
    # fallback (user)
    $Result.actions += ('pip_install_upgrade: ' + $PackageName + ' (--user fallback)')
    $inst2 = Run-PyCapture -PyExe $PyExe -PyBase $PyBase -Args @('-m','pip','install','-U',$PackageName,'--user','--disable-pip-version-check','--no-input')
    $Result.pip_tail = Tail-Text -Text ($inst.out + "\n---\n" + $inst2.out)
    if ($inst2.rc -ne 0) {
      throw ('pip install -U ' + $PackageName + ' failed')
    }
  }

  # re-check
  $chk2 = Run-PyCapture -PyExe $PyExe -PyBase $PyBase -Args $CheckArgs
  if ($chk2.rc -ne 0) {
    $Result.pip_tail = Tail-Text -Text (Nz $Result.pip_tail + "\n" + $chk2.out)
    throw ($PackageName + ' still not available after install')
  }
  $Result.tools[$ToolKey] = ($chk2.out.Trim())
}

$ts = Get-UtcIso
$result = [ordered]@{
  schema = 'bootstrap_tools_v1'
  ts_utc = $ts
  ok = $false
  exit_code = 2
  python = $null
  pip = $null
  tools = @{ ruff = $null; pyinstaller = $null }
  actions = @()
  pip_tail = $null
  error = $null
}

try {
  $py = Resolve-Python
  if (-not $py) {
    $result.error = 'Python not found (expected: py or python in PATH)'
    $result.exit_code = 2
    $result | ConvertTo-Json -Depth 12 -Compress
    exit 2
  }

  $pyExe = $py.exe
  $pyBase = [string[]]$py.args

  $pyPath = & $pyExe @($pyBase + @('-c', 'import sys; print(sys.executable)'))
  if ($LASTEXITCODE -ne 0) { throw 'Failed to query python executable' }
  $result.python = ($pyPath | Select-Object -First 1)

  $pipVer = & $pyExe @($pyBase + @('-m','pip','--version'))
  if ($LASTEXITCODE -ne 0) { throw 'pip not available' }
  $result.pip = ($pipVer | Select-Object -First 1)

  # Ensure ruff
  Ensure-PipPkg -PyExe $pyExe -PyBase $pyBase -PackageName 'ruff' -CheckArgs @('-m','ruff','--version') -ToolKey 'ruff' -Result $result

  # Ensure pyinstaller
  Ensure-PipPkg -PyExe $pyExe -PyBase $pyBase -PackageName 'pyinstaller' -CheckArgs @('-m','PyInstaller','--version') -ToolKey 'pyinstaller' -Result $result

  $result.ok = $true
  $result.exit_code = 0
  $result | ConvertTo-Json -Depth 12 -Compress
  exit 0
}
catch {
  $result.ok = $false
  $result.exit_code = 2
  $result.error = ($_.Exception.Message)
  $result | ConvertTo-Json -Depth 12 -Compress
  exit 2
}
